use spire_env::*;
use spire_core::{combat::rng::Partition,content::Character};
fn config()->RunSessionConfig{RunSessionConfig{character:Character::Watcher,ascension:0,partition:Partition::Test,boss_history:RunBossHistory::Act1GuardianUnseen,capacities:RunCapacities::m10_default(),record_replay:true}}
#[test]
fn m22_descriptor_covers_producer_union(){let d=m22_run_observation_spec(&config().capacities).unwrap().descriptor();assert_eq!(d["vocabularies"]["card"].as_array().unwrap().len(),35);assert_eq!(d["semantics"]["finite_content"]["relics"].as_array().unwrap().len(),18);assert_eq!(d["semantics"]["finite_content"]["potions"].as_array().unwrap().len(),7);}
#[test]
fn m22_session_normal_reset_and_recorded_ordinal(){let mut s=RunSession::new_m22(config()).unwrap();let first=s.reset(Some(7)).unwrap();let next=s.reset(None).unwrap();assert_ne!(first.token,next.token);assert_eq!(s.record().unwrap().unwrap().ordinal,1);let report=replay_run(&s.record().unwrap().unwrap(),config().capacities).unwrap();assert_eq!(s.reproduction().unwrap().latest_decision.unwrap().unwrap(),report.final_decision);}
#[test]
fn m22_session_rejects_foreign_config_and_history(){for ch in [Character::Ironclad,Character::Silent,Character::Defect]{let mut c=config();c.character=ch;assert!(RunSession::new_m22(c).is_err());}let mut c=config();c.ascension=1;assert!(RunSession::new_m22(c).is_err());for h in [RunBossHistory::AwakenedUnseen,RunBossHistory::M17DefectAct1{act1:RunAct1BossTarget::Guardian},RunBossHistory::M15SilentHeart{act1:RunAct1BossTarget::Guardian,act2:RunAct2BossTarget::Champ,act3:RunAct3BossTarget::AwakenedOne}]{let mut c=config();c.boss_history=h;assert!(RunSession::new_m22(c).is_err());}}
#[test]
fn m22_session_tokens_indices_and_owned_boundaries_are_atomic(){let mut s=RunSession::new_m22(config()).unwrap();let mut peer=RunSession::new_m22(config()).unwrap();let a=s.reset(Some(7)).unwrap();let b=peer.reset(Some(7)).unwrap();let before=s.reproduction().unwrap();for (token,index) in [(b.token,0),(a.token,-1),(a.token,i64::MAX)]{assert!(s.step(token,RunActionIndex(index)).is_err());assert_eq!(s.reproduction().unwrap(),before);}let next=s.step(a.token,RunActionIndex(0)).unwrap();assert!(!next.terminated&&!next.truncated);assert_eq!(a.observation.action_mask.iter().filter(|n|**n==1).count(),2);assert!(matches!(s.step(a.token,RunActionIndex(0)),Err(RunSessionError::StaleToken)));}
#[test]
fn m22_replay_strict_json_and_identities(){let mut s=RunSession::new_m22(config()).unwrap();s.reset(Some(7)).unwrap();let b=s.decision().unwrap();s.step(b.token,RunActionIndex(0)).unwrap();let r=s.record().unwrap().unwrap();let bytes=r.to_json().unwrap();assert_eq!(RunEpisodeRecord::from_json(&bytes).unwrap(),r);let original:serde_json::Value=serde_json::from_slice(&bytes).unwrap();for key in ["profile_id","schema_id","rules_id","content_id","seed_adapter_id","rng_id","reward_id"]{let mut v=original.clone();v[key]=serde_json::json!("wrong");assert!(RunEpisodeRecord::from_json(&serde_json::to_vec(&v).unwrap()).is_err(),"{key}");}for pointer in ["","/config","/config/capacities","/steps/0","/steps/0/action"]{let mut v=original.clone();v.pointer_mut(pointer).unwrap().as_object_mut().unwrap().insert("extra".into(),serde_json::json!(1));assert!(RunEpisodeRecord::from_json(&serde_json::to_vec(&v).unwrap()).is_err(),"{pointer}");}let text=String::from_utf8(bytes).unwrap();let duplicate=text.replacen("\"seed\":7","\"seed\":7,\"seed\":8",1);assert_ne!(text,duplicate);assert!(RunEpisodeRecord::from_json(duplicate.as_bytes()).is_err());let mut wrong=r.clone();wrong.steps[0].reward+=1;assert!(replay_run(&wrong,config().capacities).is_err());let mut wrong=original.clone();wrong["ordinal"]=serde_json::json!(-1);assert!(RunEpisodeRecord::from_json(&serde_json::to_vec(&wrong).unwrap()).is_err());let mut wrong=r.clone();wrong.observation_fingerprint[0]^=1;assert!(wrong.to_json().is_err());}
#[test]
fn m22_capacity_failures_are_exact(){let mut s=RunSession::new_m22(config()).unwrap();s.reset(Some(7)).unwrap();let rep=s.reproduction().unwrap();let d=rep.latest_decision.unwrap().unwrap();for (group,required) in [("permanent_cards",10),("potions",3),("offers",2),("actions",2)]{let mut caps=config().capacities;let capacity=required-1;match group{"permanent_cards"=>caps.permanent_cards=capacity,"relics"=>caps.relics=capacity,"potions"=>caps.potions=capacity,"offers"=>caps.offers=capacity,_=>caps.actions=capacity}let e=encode_run_m22(&d,None,&caps).unwrap_err();assert_eq!(e,RunSessionError::Capacity{group,required,capacity});}}
#[test]
fn m22_batch_preflights_all_slots(){for workers in [1,2]{let mut b=RunBatch::new_m22(vec![config();2],workers).unwrap();let initial=b.reset(&[Some(7),Some(11)]).unwrap();let before=[b.reproduction(0).unwrap(),b.reproduction(1).unwrap()];assert!(b.step(&[initial[0].token],&[RunActionIndex(0)]).is_err());assert!(b.step(&[initial[0].token,initial[0].token],&[RunActionIndex(0);2]).is_err());assert!(b.step(&[initial[0].token,initial[1].token],&[RunActionIndex(0),RunActionIndex(-1)]).is_err());assert_eq!([b.reproduction(0).unwrap(),b.reproduction(1).unwrap()],before);let actual=b.step(&initial.iter().map(|r|r.token).collect::<Vec<_>>(),&[RunActionIndex(0);2]).unwrap();for i in 0..2{let mut s=RunSession::new_m22(config()).unwrap();let first=s.reset(Some([7,11][i])).unwrap();let expected=s.step(first.token,RunActionIndex(0)).unwrap();assert_eq!(actual[i].boundary.observation,expected.boundary.observation);assert_eq!(actual[i].reward,expected.reward);assert_eq!(b.record(i).unwrap(),s.record().unwrap());}}assert!(RunBatch::new_m22(vec![],1).is_err());assert!(RunBatch::new_m22(vec![config()],0).is_err());let mut foreign=config();foreign.character=Character::Silent;assert!(matches!(RunBatch::new_m22(vec![config(),foreign],2),Err(RunBatchError::Input{slot:Some(1),..})));}
#[test]
fn m22_replay_delivery_capacity_keeps_actual_accepted_prefix(){let mut c=config();c.capacities.map_nodes=1;let mut s=RunSession::new_m22(c.clone()).unwrap();let b=s.reset(Some(7)).unwrap();let error=s.step(b.token,RunActionIndex(0)).unwrap_err();assert_eq!(error,RunSessionError::DeliveryFault("post-step Run encoding failed"));let r=s.record().unwrap().unwrap();assert_eq!(r.steps.len(),1);let f=r.fault.as_ref().unwrap();assert!(f.committed&&f.gameplay_recorded);assert_eq!(f.error.kind,RunRecordErrorKind::Capacity);let bytes=r.to_json().unwrap();let decoded=RunEpisodeRecord::from_json(&bytes).unwrap();assert_eq!(decoded,r);let report=replay_run(&decoded,c.capacities).unwrap();assert_eq!(report.accepted_count,1);assert_eq!(report.reported_fault,r.fault);assert!(report.final_decision_error.is_none());assert_eq!(report.final_decision,s.reproduction().unwrap().latest_decision.unwrap().unwrap());let before=s.reproduction().unwrap();assert!(s.reset(None).is_err());s.fail_delivery("later").unwrap();assert_eq!(s.reproduction().unwrap(),before);s.close().unwrap();assert!(s.record().unwrap().unwrap().closed);}
#[test]
fn m22_descriptor_domain_catalog_and_candidate_rows_are_exact(){use sha2::{Digest,Sha256};let caps=config().capacities;let spec=m22_run_observation_spec(&caps).unwrap();let d=spec.descriptor();let mut h=Sha256::new();h.update(b"spire-gym/run-schema/m22-watcher-act1/v1\0");h.update(serde_json::to_vec(&d).unwrap());assert_eq!(spec.fingerprint(),<[u8;32]>::from(h.finalize()));let finite=&d["semantics"]["finite_content"];assert_eq!(finite["playable_encounters"].as_array().unwrap().len(),12);assert_eq!(finite["playable_enemies"].as_array().unwrap().len(),16);assert_eq!(finite["map_only_boss_icons"].as_array().unwrap().len(),3);assert_eq!(finite["generated_cards"],serde_json::json!(["miracle","smite","safety"]));assert_eq!(finite["capture_law"]["key_fields"],serde_json::json!(["act","floor","node_id","visit","source_tag"]));assert_eq!(finite["capture_law"]["singleton_requests_rng"],true);let mut s=RunSession::new_m22(config()).unwrap();let b=s.reset(Some(7)).unwrap();let o=&b.observation;assert_eq!(o.action_mask.len(),caps.actions);assert_eq!(&o.action_mask[..3],&[1,1,0]);let g=o.group("actions").unwrap();assert_eq!(g.occupied.as_ref().unwrap()[..3],[1,1,0]);let count=g.shape[1];assert!(g.values[count*2..].iter().all(|x|*x==0));assert!(g.known[count*2..].iter().all(|x|*x==0));assert_eq!(o.group("context").unwrap().known[1],1);}
#[test]
fn m22_replay_watcher_verbs_are_strict_and_old_profiles_reject(){use spire_core::{combat::{CombatAction,Stance},run::GameAction};let mut s=RunSession::new_m22(config()).unwrap();s.reset(Some(7)).unwrap();let base=s.record().unwrap().unwrap();for a in [CombatAction::DeselectCard{instance:4},CombatAction::ChooseStance{stance:Stance::Calm},CombatAction::ConfirmSelection,CombatAction::SelectCard{instance:4}]{let mut r=base.clone();r.steps.push(RunRecordedStep{action:GameAction::Combat(a),reward:0,terminal:None});let wire=r.to_json().unwrap();assert_eq!(RunEpisodeRecord::from_json(&wire).unwrap(),r);let mut v:serde_json::Value=serde_json::from_slice(&wire).unwrap();v["steps"][0]["action"]["hidden"]=serde_json::json!(1);assert!(RunEpisodeRecord::from_json(&serde_json::to_vec(&v).unwrap()).is_err());assert!(replay_run(&r,config().capacities).is_err(),"codec witness is not an offered gameplay action");}let mut c=config();c.character=Character::Silent;let mut old=RunSession::new_m12(c).unwrap();old.reset(Some(7)).unwrap();let mut r=old.record().unwrap().unwrap();r.steps.push(RunRecordedStep{action:GameAction::Combat(CombatAction::ChooseStance{stance:Stance::Calm}),reward:0,terminal:None});assert!(r.to_json().is_err());}
#[test]
fn m22_encode_initial_hidden_rng_and_physical_handles_do_not_leak(){let mut a=RunSession::new_m22(config()).unwrap();let mut b=RunSession::new_m22(config()).unwrap();let first=a.reset(Some(7)).unwrap();let other=b.reset(Some(11)).unwrap();assert_eq!(first.observation,other.observation);let mut d=a.reproduction().unwrap().latest_decision.unwrap().unwrap();let original=encode_run_m22(&d,None,&config().capacities).unwrap();for c in &mut d.objects{c.instance+=1000;}assert_eq!(encode_run_m22(&d,None,&config().capacities).unwrap(),original);d.objects[0].id=spire_core::content::CardId::Strike;assert!(encode_run_m22(&d,None,&config().capacities).is_err());}
#[test]
fn m22_batch_post_dispatch_capacity_retains_indexed_peers(){for workers in [1,2]{let mut small=config();small.capacities.map_nodes=1;let mut b=RunBatch::new_m22(vec![config(),small],workers).unwrap();let bounds=b.reset(&[Some(7);2]).unwrap();let tokens=bounds.iter().map(|r|r.token).collect::<Vec<_>>();let err=b.step(&tokens,&[RunActionIndex(0);2]).unwrap_err();let RunBatchError::Fault{slots}=err else{panic!("expected actual encoding fault")};assert_eq!(slots.len(),2);assert!(slots[0].committed&&slots[0].delivery_lost);assert!(slots[1].committed&&!slots[1].delivery_lost);let actual=b.record(1).unwrap().unwrap();assert_eq!(actual.steps.len(),1);assert_eq!(actual.fault.as_ref().unwrap().error.capacity.as_ref().unwrap().group,"map_nodes");let before=[b.reproduction(0).unwrap(),b.reproduction(1).unwrap()];assert!(b.step(&tokens,&[RunActionIndex(0);2]).is_err());assert_eq!([b.reproduction(0).unwrap(),b.reproduction(1).unwrap()],before);}}
#[test]
fn m22_batch_all_reset_slots_and_seed_semantics_are_full(){for workers in [1,2]{let mut b=RunBatch::new_m22(vec![config();2],workers).unwrap();let first=b.reset(&[Some(7),Some(11)]).unwrap();let second=b.reset(&[Some(7),None]).unwrap();assert_eq!(b.record(0).unwrap().unwrap().ordinal,0);assert_eq!(b.record(1).unwrap().unwrap().ordinal,1);let before=[b.reproduction(0).unwrap(),b.reproduction(1).unwrap()];assert!(b.reset(&[None]).is_err());assert_eq!([b.reproduction(0).unwrap(),b.reproduction(1).unwrap()],before);assert_ne!(first[0].token,second[0].token);assert_ne!(first[1].token,second[1].token);}}
#[test]
fn m22_keeps_frozen_m21_descriptor_bytes(){let spec=watcher_combat_observation_spec(&combat_policy_capacities()).unwrap();assert_eq!(spec.fingerprint().iter().map(|b|format!("{b:02x}")).collect::<String>(),"e7e49e88d50c947fde064a764153a5846ba3dc6c8298116f03e8126383b51e34");}
#[test]
fn m22_encode_rejects_false_ready_or_downstream_boundaries(){let mut s=RunSession::new_m22(config()).unwrap();s.reset(Some(7)).unwrap();let original=s.reproduction().unwrap().latest_decision.unwrap().unwrap();for (act,floor) in [(0,0),(1,17),(2,16),(3,34)]{let mut d=original.clone();d.act=act;d.floor=floor;d.room.as_mut().unwrap().kind=spire_core::run::RoomViewKind::Act2Ready;d.room.as_mut().unwrap().choices.clear();d.candidates.clear();assert!(encode_run_m22(&d,None,&config().capacities).is_err(),"invalid ready {act}/{floor}");}}
